pub struct S;
impl S {
    pub fn f(&self) {}
    pub fn g() {}
}

pub struct S;
impl S {
    pub fn f(a: u8, self) {}
}

pub trait T {
    pub fn f();
}

pub struct S;
pub trait T {
    fn f();
}
impl T for S {
    pub fn f() {}
}

pub struct S {
    pub pub a: u8,
}

unsafe extern \C" {
    fn f(..., a: u8);
}
"
